<div class="wrap ses-admin"><h1>Páginas Protegidas</h1><div class="ses-card"><p>Estas páginas não recebem enriquecimento automático.</p><table class="widefat striped"><thead><tr><th>ID</th><th>Título</th><th>Slug</th><th>Status SES</th><th>Proteção</th></tr></thead><tbody><?php foreach ((array) ($pages ?? array()) as $page) : ?><tr><td><?php echo esc_html($page->ID); ?></td><td><a href="<?php echo esc_url(get_edit_post_link($page->ID)); ?>"><?php echo esc_html(get_the_title($page)); ?></a></td><td><?php echo esc_html($page->post_name); ?></td><td><?php echo esc_html(SES_Batch_Processor::status_label(get_post_meta($page->ID, '_ses_enrichment_status', true))); ?></td><td><?php echo get_post_meta($page->ID, '_ses_protected', true) ? 'Protegida' : 'Livre'; ?></td></tr><?php endforeach; ?></tbody></table></div></div>
